        {"id": "BAU_RAT:radstaender","kopf": "Gespräch über: Wir sollten Fahrräder an festen Plätzen abstellen. Jemand sagt: „Wer spät kommt, stellt sein Rad einfach vor die Tür; wir reden nicht darüber.“","optionen": [{"text": "Wie viele Plätze fehlen? Wir suchen eine Lösung mit freiem Eingang.","ok": true,"info": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","warum": [{"text": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","ok": true},{"text": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest.","ok": false},{"text": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail.","ok": false}]},{"text": "Wir könnten die Fahrradständer beim nächsten Schulfest gemeinsam bunt bemalen.","ok": false,"info": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest."},{"text": "Wer spät kommt, stellt sein Rad einfach vor die Tür; wir reden nicht darüber.","ok": false,"info": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail."}]},
        {"id": "BAU_RAT:tauschregal","kopf": "Gespräch über: Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen. Jemand sagt: „Wer schon neue Stifte hat, soll über das Tauschregal allein entscheiden.“","optionen": [{"text": "Welche Sachen werden gebraucht? Wir fragen auch Kinder mit wenig Material.","ok": true,"info": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","warum": [{"text": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","ok": true},{"text": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest.","ok": false},{"text": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail.","ok": false}]},{"text": "Wir könnten erst einmal Farben für das neue Schild am Tauschregal sammeln.","ok": false,"info": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest."},{"text": "Wer schon neue Stifte hat, soll über das Tauschregal allein entscheiden.","ok": false,"info": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail."}]},
        {"id": "BAU_RAT:lernpause","kopf": "Gespräch über: Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Jemand sagt: „Wer nach der Bewegungspause noch unruhig ist, hat beim Planen keine Stimme.“","optionen": [{"text": "Was hilft beim Neustart? Wir vergleichen die Erfahrungen nach der Pause.","ok": true,"info": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","warum": [{"text": "Der Beitrag lädt dazu ein, die strittigen Gründe zu prüfen.","ok": true},{"text": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest.","ok": false},{"text": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail.","ok": false}]},{"text": "Wir könnten für die Pause zunächst die beliebtesten Musikrichtungen sammeln.","ok": false,"info": "Der Beitrag legt eine Entscheidung ohne weitere Prüfung fest."},{"text": "Wer nach der Bewegungspause noch unruhig ist, hat beim Planen keine Stimme.","ok": false,"info": "Der Beitrag verschiebt das Gespräch auf ein anderes Detail."}]}
